     "ex": "import pandas as pd\ns = pd.Series([5, 7, 3, 9, 4, 8, 6, 10], index=pd.date_range(\"2026-09-01\", periods=8, freq=\"D\", tz=\"UTC\"))\nprint(s.tz_convert(\"Africa/Cairo\").index[0])\nprint(s.resample(\"W\").sum())",
